package net.officefloor.hq.app;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * GET /api/invoices?projectId=&lt;id&gt;&amp;sort=&lt;key&gt; — the invoices of one project. Scoped to a
 * project (the detail page lists ITS invoices), so the project id arrives as a query parameter. The
 * optional {@code sort} key chooses the order: {@code due} is earliest-due-first, anything else (and
 * the default) is id order. Wired by officefloor/rest/api/invoices.GET.yml.
 */
public class ListInvoices {

    public void service(@RequestParam("projectId") String projectId,
            @RequestParam("sort") String sort,
            InvoiceRepository invoices, ObjectResponse<List<InvoiceView>> response) {
        Long id = Long.valueOf(projectId);
        List<Invoice> rows = "due".equals(sort)
                ? invoices.findByProjectIdOrderByDueDateAscIdAsc(id)
                : invoices.findByProjectIdOrderByIdAsc(id);
        List<InvoiceView> view = rows.stream().map(InvoiceView::of).toList();
        response.send(view);
    }
}
package net.officefloor.hq.app;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

/** Data access for {@link Invoice}. A Spring bean, injected into the OfficeFloor logic classes. */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** The invoices of one project, in id order — the shape the project detail page lists. */
    List<Invoice> findByProjectIdOrderByIdAsc(Long projectId);

    /** The invoices of one project, earliest due date first (ties broken by id for a stable order). */
    List<Invoice> findByProjectIdOrderByDueDateAscIdAsc(Long projectId);
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.time.LocalDate;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * An invoice the user raises against a project: an amount and the id of the project it is for. Maps
 * the {@code invoices} table (Flyway V4__invoices.sql); the id is IDENTITY-generated on create. The
 * amount is a {@link BigDecimal} because it is money (fixed scale, no float drift).
 */
@Entity
@Table(name = "invoices")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id", nullable = false)
    private Long projectId;

    @Column(nullable = false)
    private BigDecimal amount;

    /**
     * The lifecycle status of the invoice: DRAFT when raised, SENT once the user sends it, PAID once
     * the user takes payment. Payment is only allowed after it has been sent.
     */
    @Column(nullable = false)
    private String status;

    /** When the invoice went out. */
    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    /** When the invoice is due to be paid. */
    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    protected Invoice() {
    }

    public Invoice(Long projectId, BigDecimal amount, LocalDate issuedDate, LocalDate dueDate) {
        this.projectId = projectId;
        this.amount = amount;
        this.status = "DRAFT";
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** Send this invoice — the DRAFT -> SENT transition the send action performs. */
    public void markSent() {
        this.status = "SENT";
    }

    /** Whether this invoice has been sent, and so may be paid. */
    public boolean isSent() {
        return "SENT".equals(this.status);
    }

    /** Mark this invoice paid — the status transition the pay action performs. */
    public void markPaid() {
        this.status = "PAID";
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * What the API exposes for an invoice: the shape the front-end renders into the project's invoices
 * table. The amount keeps its scale (a {@link BigDecimal}) so the client formats it to two places.
 */
public record InvoiceView(Long id, Long projectId, BigDecimal amount, String status,
        String issuedDate, String dueDate) {

    public static InvoiceView of(Invoice invoice) {
        return new InvoiceView(invoice.getId(), invoice.getProjectId(), invoice.getAmount(),
                invoice.getStatus(), invoice.getIssuedDate().toString(),
                invoice.getDueDate().toString());
    }
}

